css:
.glow-send-root {
  font-family: ui-sans-serif, system-ui, sans-serif;
  padding: 8px;
  display: flex;
  flex-direction: column;
  gap: 4px;
  align-items: stretch;
}
.glow-send-btn {
  padding: 10px 16px;
  border: none;
  border-radius: 8px;
  background: linear-gradient(135deg, #f59e0b 0%, #ef4444 100%);
  color: white;
  font-size: 14px;
  font-weight: 600;
  cursor: pointer;
  transition: transform 0.15s ease, box-shadow 0.15s ease;
  box-shadow: 0 4px 12px -2px rgba(239, 68, 68, 0.5);
}
.glow-send-btn:hover {
  transform: translateY(-1px);
  box-shadow: 0 6px 16px -2px rgba(239, 68, 68, 0.7);
}
.glow-send-hint {
  font-size: 10px;
  color: #6b7280;
  text-align: center;
}
